# Table runs for parameterized ProcessTable notebook (JSON file mode)
import json
# Derive the dependency folder path from this notebook's runtime location
# so that JSON config files are found regardless of which workspace/environment
# this notebook is deployed to. No absolute path configuration required.
_nb_path = dbutils.notebook.entry_point.getDbutils().notebook().getContext().notebookPath().get()
dep_path = _nb_path.rsplit("/", 1)[0]
_proc_offset = "../tables"
process_path  = dep_path + "/" + _proc_offset
model_name   = "SimpleAWGold"
_table_runs = []
_table_names = [
    "DimCustomer",
    "DimDate",
    "DimProduct",
    "FactSalesOrder",
    "FactSalesOrderLine",
]

for _table_name in _table_names:
    if "<ENV:" in dep_path: raise RuntimeError(f"dep_path contains unresolved ENV token: {dep_path!r} — check that all <ENV:...> variables are set before deploying")
    _cfg_path = f"/Workspace{dep_path}/table_configs/{_table_name}_config.json"
    with open(_cfg_path) as _fh:
        _table_config_str = _fh.read()
    _table_runs.append((
        _table_name,
        f"{process_path}/{model_name}_ProcessTable",
        {
            "table_name":   _table_name,
            "model_name":   model_name,
            "table_config": _table_config_str,
        },
    ))

# COMMAND ----------

# Execute all table notebooks in parallel with per-table config
from concurrent.futures import ThreadPoolExecutor, as_completed
import traceback

_errors: list[str] = []

def _run(name: str, path: str, params: dict, retries: int = 0) -> str:
    for _attempt in range(retries + 1):
        try:
            return dbutils.notebook.run(path, 3600, params)
        except Exception as _exc:
            if _attempt == retries:
                raise
            print(f'{name}: attempt {_attempt + 1} failed, retrying...')

with ThreadPoolExecutor(max_workers=1) as _pool:
    _futures = {_pool.submit(_run, n, p, cfg): n for n, p, cfg in _table_runs}
    for _fut in as_completed(_futures):
        _name = _futures[_fut]
        try:
            _result = _fut.result()
            print(f'{_name}: {_result}')
        except Exception as _exc:
            _errors.append(f'{_name}: {_exc}')
            print(f'ERROR {_name}: {_exc}')

if _errors:
    raise RuntimeError(f'Notebooks failed: {chr(10).join(_errors)}')

print('RunAllNotebooks complete.')